def clean(t):
 return t.replace(';', '; ').replace('NOT REPORTED', 'Not reported').replace('NOT VERIFIED', 'NOT VERIFIED').replace('  ', ' ')

rows = [headers]; trace = []
for no, r in enumerate(papers, 1):
 sid = r['Study_ID']; full = r['Included (Y/N)'] == 'Y'
 path = R / 'logs/metadata' / (r['DOI'].replace('/', '_') + '.json')
 if sid == 'P010': path = R / 'logs/metadata/P010.json'
 if sid == 'P011': path = R / 'logs/metadata/GeFeS.json'
 meta = json.loads(path.read_text())['message'] if path.exists() else {}
 count = meta.get('is-referenced-by-count', 'NOT VERIFIED')
 metrics = 'Accuracy, selected-feature count or reduction; exact definitions NOT VERIFIED from full text.'
 methods = clean(r['GA_Variant_or_Hybrid'])
 data = clean(r['Datasets_and_Sources'])
 if full:
  data = dataset_summaries[sid]
  methods = method_summaries[sid]
  metrics = {
   'P004': 'Balanced accuracy, sensitivity, specificity, classification accuracy, feature-recovery F1, selected features. Feature-recovery F1 is a separate target.',
   'P003': 'Macro-F1, selected-feature count, execution time. Scores aggregate across feature counts and repeated executions.',
   'P013': 'Hypervolume and inverted generational distance, classification error, feature count. HV/IGD measure Pareto-front quality.',
   'P017': 'Hypervolume, inverted generational distance, minimum classification error, feature ratio. Front metrics are not accuracy.',
   'P018': 'Classification accuracy, ANN error/loss, selected-feature count, execution-time comparisons. ANN loss-to-accuracy semantics need verification.',
   'P021': 'Accuracy, weighted F1, fixed feature count, search time in minutes, reference-batch prediction time in seconds.',
   'P022': 'Reported predictive score, feature count and reduction. The results text uses accuracy to denote F1.'
  }.get(sid, 'Classification accuracy, selected-feature count or reduction, and computational cost as defined by the source. ' + ('Time to a target score, not fixed-budget runtime.' if sid == 'P002' else 'NFE is reported instead of measured wall-clock time.' if sid == 'P006' else 'Selection-only runtime is separated from classification time.' if sid == 'P010' else 'Measured runtime is not clearly reported.' if sid == 'P005' else 'Runtime is study- and protocol-specific.'))
 else:
  methods = 'GA-based feature selection identified by the verified title/accessible abstract. Detailed representation, operators, settings and classifiers: NOT VERIFIED.'
  data = 'NOT VERIFIED — full-text dataset table unavailable.'
  if sid == 'P007': data = 'CIRA-CIC-DOHBrw-2020, UNSW-NB15 and Bot-IoT (institutional abstract only; full protocol NOT VERIFIED).'
  if sid == 'P015': metrics = 'Publisher abstract: classification performance, classification starting time, classification execution time. Exact metrics and measurements: NOT VERIFIED.'
 reg = registry[sid]
 bibliographic_detail = 'vol. ' + reg['volume'] + ', ' + ('pp. ' if '-' in reg['pages_or_article_no'] else 'article ') + reg['pages_or_article_no']
 locator = r['Evidence_Page_Table_Figure'].split(';version audit')[0].split(';version')[0]
 locator = locator.replace('Tables', 'Tables ').replace('Table', 'Table ').replace('PDFp', 'PDF p. ').replace('fulltextXML', 'full-text XML').replace('physicalPDFpagesunavailable', 'physical PDF pages unavailable')
 reference = f"{r['Authors'].replace('; ', ', ')}. {r['Exact_Title']}. {r['Journal_or_Conference']}, {bibliographic_detail}, {r['Year']}.\nhttps://doi.org/{r['DOI']}\nEvidence: {sid}. " + (locator if full else 'Metadata/abstract only; full-text findings NOT VERIFIED.')
 rows.append([no, int(r['Year']), r['Authors'].replace('; ', ', '), r['Exact_Title'], abstracts[sid], r['Journal_or_Conference'], count, data, methods, metrics, results.get(sid, 'NOT VERIFIED — the complete experimental tables, evaluation protocol, feature counts and runtime have not been accessed. No numerical findings are inferred.'), limitations.get(sid, 'Full text unavailable. Detailed limitations cannot be assessed; missing access is a review-coverage limitation, not evidence that the paper’s method is deficient.'), reference])
 trace.append({'row': no+1, 'Study_ID': sid, 'full_text': full, 'citation_count_metadata': str(path.relative_to(R)), 'citation_source': 'Crossref is-referenced-by-count snapshot retrieved 9 October 2026; not Google Scholar and not a live current count', 'source': r['Evidence_Page_Table_Figure']})

assert len(rows) == len(papers)+1 and all(len(row) == 13 for row in rows)
(R/'tmp/sample_style_matrix_data.json').write_text(json.dumps({'rows': rows, 'trace': trace, 'sample_sha256': hashlib.sha256(sample.read_bytes()).hexdigest()}, indent=2, ensure_ascii=False))
print('Prepared',len(papers),'records with exact sample headings')
